VkResult vkNegotiateLoaderLayerInterfaceVersion(VkNegotiateLayerInterface* pVersionStruct) {
    assert(pVersionStruct != NULL);
    assert(pVersionStruct->sType == VK_STRUCTURE_TYPE_NEGOTIATE_LOADER_LAYER_INTERFACE_VERSION);

    // Check if the loader is compatible with the layer's supported interface version
    static constexpr uint32_t VK_LOADER_LAYER_INTERFACE_VERSION_2 = 2;
    if (pVersionStruct->loaderLayerInterfaceVersion >= VK_LOADER_LAYER_INTERFACE_VERSION_2) {
        // Loader is compatible, update the version struct with the layer's info
        pVersionStruct->loaderLayerInterfaceVersion = CURRENT_LOADER_LAYER_INTERFACE_VERSION;
        pVersionStruct->pfnGetInstanceProcAddr = vkGetInstanceProcAddr;
        pVersionStruct->pfnGetDeviceProcAddr = vkGetDeviceProcAddr;
        return VK_SUCCESS;
    } else {
        // Loader is too old, not compatible
        return VK_ERROR_INCOMPATIBLE_DRIVER;
    }
}

