VkResult vkAllocateCommandBuffers(VkDevice device, const VkCommandBufferAllocateInfo* pAllocateInfo,
                                  VkCommandBuffer* pCommandBuffers) {
    LOG("Josh-Layer: %s\n", __func__);
    // Get dispatch for device
    auto* handleInfo = sUniqueVkHandles.getHandleInfo((UniqueVkHandle)(uintptr_t)device);
    if (!handleInfo) {
        LOG("ERROR: Unable to find handleInfo for uniqueVkHandle=0x%p\n", device);
    }
    VulkanDispatch* nextLayerDispatch = handleInfo ? handleInfo->dispatch : nullptr;
    // Converting device to native VkDevice handle
    VkDevice unique_VkDevice = device;
    {
        auto* handleInfo =
            sUniqueVkHandles.getHandleInfo((UniqueVkHandle)(uintptr_t)unique_VkDevice);
        if (!handleInfo) {
            LOG("ERROR: Unable to find handleInfo for uniqueVkHandle=0x%p\n", unique_VkDevice);
        }
        device = handleInfo ? (VkDevice)(uintptr_t)handleInfo->nativeHandle : VK_NULL_HANDLE;
    }
    // API call to next layer
    VkResult vkAllocateCommandBuffers_VkResult_return = (VkResult)0;
    vkAllocateCommandBuffers_VkResult_return =
        nextLayerDispatch->vkAllocateCommandBuffers(device, pAllocateInfo, pCommandBuffers);
    if (vkAllocateCommandBuffers_VkResult_return == VK_SUCCESS) {
        auto count = pAllocateInfo->commandBufferCount;
        for (size_t i = 0; i < count; ++i) {
            // Creating unique handle for pCommandBuffers[i]
            UniqueVkHandle unique_VkCommandBuffer = sUniqueVkHandles.addDispatchableHandle(
                (uint64_t)(uintptr_t)pCommandBuffers[i], (uint64_t)(uintptr_t)unique_VkDevice);
            LOG("%s phys=0x%p mapped to 0x%lX\n", __func__, pCommandBuffers[i],
                unique_VkCommandBuffer);
            pCommandBuffers[i] = (VkCommandBuffer)(uintptr_t)unique_VkCommandBuffer;
        }
    }
    return vkAllocateCommandBuffers_VkResult_return;
}

